extern "C" float sqrtf(float);

typedef float rational_t;

inline rational_t fast_recip_sqrt(rational_t x)
{
  return 1.0F/(rational_t)sqrtf(x);
}

#define SMALL_DIST 0.0001f

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  vector3d() {}
  vector3d(T _x, T _y, T _z) : x(_x), y(_y), z(_z) {}

  inline vector3d& operator = ( const vector3d& v )
  { x = v.x; y = v.y; z = v.z; return *this; }

  inline vector3d& operator *= ( T d )
  { x *= d; y *= d; z *= d; return *this; }

  inline T length2() const
  { return x*x + y*y + z*z; }

  inline vector3d& normalize()
  {
    T l2 = length2();
    if (l2>SMALL_DIST*SMALL_DIST)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

inline vector3d operator - (const vector3d& a, const vector3d& b)
{ return vector3d(a.x - b.x, a.y - b.y, a.z - b.z); }

class entity
{
public:
  const vector3d& get_abs_position() const;
};

class ai_locomotion
{
  virtual void anchor();
  char prefix[200];
  bool in_service;
  int type;
  bool facing;
  bool playing_face_anim;
  vector3d face_dir;
  rational_t turn_speed;

public:
  entity *get_my_entity() const;
  bool set_facing_point(const vector3d &pt, rational_t mod);
};

bool ai_locomotion::set_facing_point(const vector3d &pt, rational_t mod)
{
  if(!in_service)
  {
    facing = true;

    face_dir = pt - get_my_entity()->get_abs_position();
    face_dir.normalize();

    turn_speed = mod;
  }
  else
    facing = false;

  return(facing);
}
